import { Routes } from '@angular/router';

export const routes: Routes = [
  {
    path: '',
    loadComponent: () => import('./ccl-test/ccl-test').then(m => m.CclTest),
    title: 'MHA PDS - CCL Test'
  },
  {
    path: 'config',
    loadComponent: () => import('./config-editor/config-editor').then(m => m.ConfigEditorComponent),
    title: 'MHA PDS Configuration'
  },
  {
    path: 'logs',
    loadComponent: () => import('./logs/logs').then(m => m.LogsComponent),
    title: 'MHA PDS Logs'
  },
  {
    path: 'patients',
    loadComponent: () => import('./patients/patients').then(m => m.PatientsComponent),
    title: 'MHA PDS Patients'
  }
];
