import { ChangeDetectionStrategy, Component, computed, inject } from '@angular/core';
import { buildVersion, packageVersion, gitBranch } from '../version';
import { AppStatusService } from '../services/app-status.service';

/**
 * Component to display application version information and offline mode status
 * Version is auto-generated at build time by scripts/build-version.js
 */
@Component({
  selector: 'app-app-version',
  imports: [],
  templateUrl: './app-version.html',
  styleUrl: './app-version.scss',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class AppVersion {
  private appStatus = inject(AppStatusService);

  /**
   * The current application version string, including branch (e.g., v1.0.0-master)
   * This is generated at build time by scripts/build-version.js
   */
  readonly buildVersion = buildVersion;

  /**
   * The package version from package.json (e.g., 1.0.0)
   */
  readonly packageVersion = packageVersion;

  /**
   * The current git branch (e.g., master, develop)
   */
  readonly gitBranch = gitBranch;

  /**
   * Read-only signal for offline mode status
   */
  readonly isOfflineMode = computed(() => this.appStatus.offlineMode());
}
